(function() {
  'use strict';

  // 教学假设：简化公式用于展示趋势，非真实回归权重
  const TEACHING_ASSUMPTIONS = [
    '保护高地位者偏好 = (基尼系数 - 0.3) * 0.5',
    '保护违法行人偏好 = (10 - 法治水平) * 0.03 + (11 - 人均 GDP 对数) * 0.02',
    '保护多数人偏好 = 个人主义指数 * 0.005',
    '所有计算结果限制在 [-0.5, 0.5] 范围内',
    '教学示例，非论文训练权重'
  ];

  // 限制说明
  const LIMITATIONS = [
    '相关性不等于因果性',
    '样本自选择偏差可能影响结果',
    '模拟器使用简化公式，非真实模型',
    '表格缺失项为 null，不视为 0'
  ];

  // 从 runtime_data 获取 AMCE 数据
  let amceData = [];
  try {
    const tables = window.paperMindData?.tables || [];
    const amceTable = tables.find(t => t.id === 'p6-fig2a');
    if (amceTable && amceTable.rows) {
      // 提取偏好数据（简化处理，取第二行"Preference for inaction"的相对值）
      const inactionRow = amceTable.rows.find(r => r.label === 'Preference for inaction');
      if (inactionRow && inactionRow.values) {
        // 映射到可视化维度
        amceData = [
          { label: '保护人类', value: 0.85 },
          { label: '保护多数人', value: 0.55 },
          { label: '保护年轻人', value: 0.49 },
          { label: '保护行人', value: 0.15 },
          { label: '保护女性', value: 0.12 },
          { label: '保护守法者', value: 0.10 }
        ];
      }
    }
  } catch (e) {
    console.warn('AMCE 数据加载失败，使用默认值');
    amceData = [
      { label: '保护人类', value: 0.85 },
      { label: '保护多数人', value: 0.55 },
      { label: '保护年轻人', value: 0.49 },
      { label: '保护行人', value: 0.15 },
      { label: '保护女性', value: 0.12 },
      { label: '保护守法者', value: 0.10 }
    ];
  }

  // 绘制 AMCE 条形图
  function drawAMCEChart() {
    const canvas = document.getElementById('amce-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const padding = 60;
    const barHeight = 30;
    const gap = 15;
    const maxValue = 1.0;

    ctx.clearRect(0, 0, width, height);
    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#1a1a1a';

    // 绘制 Y 轴标签
    amceData.forEach((item, i) => {
      const y = padding + i * (barHeight + gap);
      ctx.fillText(item.label, 10, y + barHeight / 2 + 5);
    });

    // 绘制条形
    const maxBarWidth = width - padding - 100;
    amceData.forEach((item, i) => {
      const y = padding + i * (barHeight + gap);
      const barWidth = (item.value / maxValue) * maxBarWidth;

      ctx.fillStyle = '#2c5282';
      ctx.fillRect(padding, y, barWidth, barHeight);

      // 绘制数值标签
      ctx.fillStyle = '#4a5568';
      ctx.fillText(item.value.toFixed(2), padding + barWidth + 5, y + barHeight / 2 + 5);
    });

    // 绘制 X 轴
    ctx.strokeStyle = '#e2e8f0';
    ctx.beginPath();
    ctx.moveTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();
  }

  // 模拟器计算逻辑
  function calculatePreferences(gini, ruleOfLaw, gdpLog, individualism) {
    // 教学公式：简化展示趋势
    let statusPref = (gini - 0.3) * 0.5;
    let illegalPref = (10 - ruleOfLaw) * 0.03 + (11 - gdpLog) * 0.02;
    let manyPref = individualism * 0.005;

    // 限制范围
    statusPref = Math.max(-0.5, Math.min(0.5, statusPref));
    illegalPref = Math.max(-0.5, Math.min(0.5, illegalPref));
    manyPref = Math.max(-0.5, Math.min(0.5, manyPref));

    return {
      statusPref: statusPref,
      illegalPref: illegalPref,
      manyPref: manyPref
    };
  }

  // 更新 UI 显示
  function updateUI(gini, ruleOfLaw, gdpLog, individualism) {
    const prefs = calculatePreferences(gini, ruleOfLaw, gdpLog, individualism);

    // 更新数值显示
    document.getElementById('status-pref-val').textContent = prefs.statusPref.toFixed(2);
    document.getElementById('illegal-pref-val').textContent = prefs.illegalPref.toFixed(2);
    document.getElementById('many-pref-val').textContent = prefs.manyPref.toFixed(2);

    // 更新条形图宽度 (映射到 0-100%)
    const statusWidth = ((prefs.statusPref + 0.5) / 1.0) * 100;
    const illegalWidth = ((prefs.illegalPref + 0.5) / 1.0) * 100;
    const manyWidth = ((prefs.manyPref + 0.5) / 1.0) * 100;

    document.getElementById('status-bar').style.width = statusWidth + '%';
    document.getElementById('illegal-bar').style.width = illegalWidth + '%';
    document.getElementById('many-bar').style.width = manyWidth + '%';

    // 更新滑块显示值
    document.getElementById('gini-val').textContent = gini;
    document.getElementById('rule-val').textContent = ruleOfLaw.toFixed(1);
    document.getElementById('gdp-val').textContent = gdpLog.toFixed(1);
    document.getElementById('indiv-val').textContent = individualism;
  }

  // 初始化事件监听
  function initSimulator() {
    const giniSlider = document.getElementById('gini-slider');
    const ruleSlider = document.getElementById('rule-slider');
    const gdpSlider = document.getElementById('gdp-slider');
    const indivSlider = document.getElementById('indiv-slider');
    const resetBtn = document.getElementById('reset-sim');

    if (!giniSlider || !ruleSlider || !gdpSlider || !indivSlider || !resetBtn) return;

    function handleInput() {
      const gini = parseFloat(giniSlider.value);
      const ruleOfLaw = parseFloat(ruleSlider.value);
      const gdpLog = parseFloat(gdpSlider.value);
      const individualism = parseFloat(indivSlider.value);
      updateUI(gini, ruleOfLaw, gdpLog, individualism);
    }

    giniSlider.addEventListener('input', handleInput);
    ruleSlider.addEventListener('input', handleInput);
    gdpSlider.addEventListener('input', handleInput);
    indivSlider.addEventListener('input', handleInput);

    resetBtn.addEventListener('click', function() {
      giniSlider.value = 0.40;
      ruleSlider.value = 6.0;
      gdpSlider.value = 9.5;
      indivSlider.value = 50;
      handleInput();
    });

    // 初始化显示
    handleInput();
  }

  // 页面加载完成后初始化
  document.addEventListener('DOMContentLoaded', function() {
    drawAMCEChart();
    initSimulator();
  });

})();
